import { requiredEnv } from "./env.ts";
import { HttpError } from "./errors.ts";
import { opaqueText } from "./records.ts";

export function requireCmsRequest(request: Request): void {
    const authorization = request.headers.get("authorization") ?? "";
    const token = authorization.startsWith("Bearer ") ? authorization.slice("Bearer ".length).trim() : "";
    if (!token || !safeEqual(token, requiredEnv("CMS_SALES_CONFIGURATOR_API_KEY"))) {
        throw new HttpError(401, "invalid CMS API key");
    }
}

export function cmsUserId(request: Request): string {
    return opaqueText(request.headers.get("x-cms-user-id"), "CMS user id", 512, 401);
}

export function requireCmsAdmin(request: Request): string {
    const role = (request.headers.get("x-cms-user-role") ?? "").trim();
    if (role !== "admin") {
        throw new HttpError(403, "CMS admin role is required");
    }
    return cmsUserId(request);
}

function safeEqual(left: string, right: string): boolean {
    if (left.length !== right.length) {
        return false;
    }
    let result = 0;
    for (let index = 0; index < left.length; index++) {
        result |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return result === 0;
}

import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";

export function requiredEnv(name: string): string {
    const value = Deno.env.get(name);
    if (!value) {
        throw new HttpError(500, `missing ${name}`);
    }
    return value;
}

export function serviceRoleKey(): string {
    const keys = Deno.env.get("SUPABASE_SECRET_KEYS");
    if (keys) {
        if (!keys.trim().startsWith("{")) {
            const first = keys
                .split(",")
                .map((value) => value.trim())
                .find(Boolean);
            if (first) {
                return first;
            }
        }
        try {
            const parsed = JSON.parse(keys);
            if (isRecord(parsed)) {
                const preferred = typeof parsed.default === "string" ? parsed.default : undefined;
                const first = Object.values(parsed).find((value) => typeof value === "string" && value);
                if (preferred || first) {
                    return (preferred ?? first) as string;
                }
            }
        } catch {
            throw new HttpError(500, "SUPABASE_SECRET_KEYS must be valid JSON");
        }
    }
    return (
        Deno.env.get("SUPABASE_SECRET_KEY") ??
        Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ??
        requiredEnv("SUPABASE_SERVICE_ROLE_KEY")
    );
}

export class HttpError extends Error {
    constructor(
        readonly status: number,
        message: string,
    ) {
        super(message);
    }
}

import { HttpError } from "./errors.ts";

export const corsHeaders = {
    "access-control-allow-origin": "*",
    "access-control-allow-headers": "authorization, content-type, x-cms-user-id, x-cms-user-role",
    "access-control-allow-methods": "GET, POST, DELETE, OPTIONS",
};

export function json(value: unknown, status = 200, headers: HeadersInit = {}): Response {
    return new Response(JSON.stringify(value), {
        status,
        headers: {
            ...corsHeaders,
            "content-type": "application/json; charset=utf-8",
            ...Object.fromEntries(new Headers(headers)),
        },
    });
}

export function privateJson(value: unknown, status = 200): Response {
    return json(value, status, { "cache-control": "private, no-store" });
}

export function optionsResponse(): Response {
    return new Response("ok", { headers: corsHeaders });
}

export function methodNotAllowed(...methods: string[]): Response {
    return new Response("Method Not Allowed", {
        status: 405,
        headers: { ...corsHeaders, allow: [...methods, "OPTIONS"].join(", ") },
    });
}

export function handleError(error: unknown): Response {
    if (error instanceof HttpError) {
        return json({ error: error.message }, error.status, { "cache-control": "private, no-store" });
    }
    console.error(error);
    return json({ error: "internal error" }, 500, { "cache-control": "private, no-store" });
}

import { HttpError } from "./errors.ts";
import type { JsonRecord } from "./types.ts";

export function isRecord(value: unknown): value is JsonRecord {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

export async function readJsonObject(request: Request): Promise<JsonRecord> {
    try {
        const value: unknown = await request.json();
        if (isRecord(value)) {
            return value;
        }
    } catch {
        // The normalized error below intentionally hides parser details.
    }
    throw new HttpError(400, "body must be a JSON object");
}

export function text(value: unknown): string | undefined {
    return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

export function requiredText(value: unknown, name: string): string {
    const result = text(value);
    if (!result) {
        throw new HttpError(400, `${name} is required`);
    }
    return result;
}

export function opaqueText(value: unknown, name: string, maxLength = 512, errorStatus = 400): string {
    if (typeof value !== "string" || !value.trim()) {
        throw new HttpError(errorStatus, `${name} is required`);
    }
    if (value !== value.trim() || /[\u0000-\u001f\u007f-\u009f]/u.test(value)) {
        throw new HttpError(errorStatus, `${name} is invalid`);
    }
    if (value.length > maxLength) {
        throw new HttpError(errorStatus, `${name} is too long`);
    }
    return value;
}

export function integer(value: unknown, name: string, required = false): number | undefined {
    if (value === undefined || value === null || value === "") {
        if (required) {
            throw new HttpError(400, `${name} is required`);
        }
        return undefined;
    }
    const result =
        typeof value === "number"
            ? value
            : typeof value === "string" && /^\d+$/.test(value.trim())
              ? Number(value.trim())
              : Number.NaN;
    if (!Number.isSafeInteger(result) || result < 1) {
        throw new HttpError(400, `${name} must be a positive integer`);
    }
    return result;
}

export function nonNegativeInteger(value: unknown, name: string): number | undefined {
    if (value === undefined || value === null || value === "") {
        return undefined;
    }
    const result =
        typeof value === "number"
            ? value
            : typeof value === "string" && /^\d+$/.test(value.trim())
              ? Number(value.trim())
              : Number.NaN;
    if (!Number.isSafeInteger(result) || result < 0) {
        throw new HttpError(400, `${name} must be a non-negative integer`);
    }
    return result;
}

export function enumValue<T extends string>(
    value: unknown,
    name: string,
    allowed: readonly T[],
    required = false,
): T | undefined {
    const result = text(value);
    if (!result && !required) {
        return undefined;
    }
    if (!result || !allowed.includes(result as T)) {
        throw new HttpError(400, `${name} must be one of: ${allowed.join(", ")}`);
    }
    return result as T;
}

export function objectValue(value: unknown, name: string): JsonRecord {
    if (!isRecord(value)) {
        throw new HttpError(400, `${name} must be an object`);
    }
    return value;
}

export function arrayValue(value: unknown, name: string, max = 500): unknown[] {
    if (!Array.isArray(value) || value.length > max) {
        throw new HttpError(400, `${name} must be an array with at most ${max} entries`);
    }
    return value;
}

export function queryInteger(request: Request, name: string, required = false): number | undefined {
    return integer(new URL(request.url).searchParams.get(name), name, required);
}

export function camelize(value: unknown): unknown {
    if (Array.isArray(value)) {
        return value.map(camelize);
    }
    if (!isRecord(value)) {
        return value;
    }
    return Object.fromEntries(
        Object.entries(value).map(([key, entry]) => [
            key.replace(/_([a-z])/g, (_, letter: string) => letter.toUpperCase()),
            opaqueJsonColumns.has(key) ? entry : camelize(entry),
        ]),
    );
}

const opaqueJsonColumns = new Set(["metadata", "payload", "proposal", "selections", "custom_items"]);

import { requiredEnv, serviceRoleKey } from "./env.ts";
import { HttpError } from "./errors.ts";
import { isRecord } from "./records.ts";
import type { JsonRecord } from "./types.ts";

const schema = "sales_configurator";

export async function rest(path: string, init: RequestInit = {}): Promise<Response> {
    const key = serviceRoleKey();
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    headers.set("accept-profile", schema);
    if (init.method && init.method !== "GET" && init.method !== "HEAD") {
        headers.set("content-profile", schema);
        headers.set("content-type", "application/json");
    }
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const response = await fetch(`${base}/rest/v1/${path}`, { ...init, headers });
    if (!response.ok) {
        throw await restError(response);
    }
    return response;
}

export async function restJson<T>(path: string, init: RequestInit = {}): Promise<T> {
    const response = await rest(path, init);
    return (await response.json()) as T;
}

export async function rpc(name: string, body: JsonRecord): Promise<unknown> {
    return await restJson(`rpc/${name}`, {
        method: "POST",
        body: JSON.stringify(body),
    });
}

export async function one(
    table: string,
    filters: Record<string, string | number>,
    select = "*",
): Promise<JsonRecord | null> {
    const params = new URLSearchParams({ select, limit: "1" });
    for (const [key, value] of Object.entries(filters)) {
        params.set(key, exactFilter(value));
    }
    const rows = await restJson<JsonRecord[]>(`${table}?${params.toString()}`);
    return rows[0] ?? null;
}

export function exactFilter(value: string | number): string {
    // This is a scalar query parameter, so URLSearchParams owns transport encoding.
    // PostgREST treats quotes around a simple `eq` operand as part of the value.
    return `eq.${value}`;
}

export async function listRows(path: string): Promise<{ rows: JsonRecord[]; total: number }> {
    const response = await rest(path, { headers: { prefer: "count=exact" } });
    const rows = (await response.json()) as JsonRecord[];
    const range = response.headers.get("content-range") ?? "";
    const total = Number(range.slice(range.lastIndexOf("/") + 1));
    return { rows, total: Number.isFinite(total) ? total : rows.length };
}

async function restError(response: Response): Promise<HttpError> {
    const data = await response.json().catch(() => null);
    const message =
        isRecord(data) && typeof data.message === "string"
            ? data.message
            : `Supabase request failed (${response.status})`;
    for (const [prefix, status] of [
        ["validation:", 400],
        ["conflict:", 409],
        ["forbidden:", 403],
        ["not_found:", 404],
    ] as const) {
        if (message.startsWith(prefix)) {
            return new HttpError(status, message.slice(prefix.length).trim());
        }
    }
    if (response.status === 400 || response.status === 422) {
        return new HttpError(400, message);
    }
    if (response.status === 409) {
        return new HttpError(409, message);
    }
    return new HttpError(502, message);
}

import { HttpError } from "./errors.ts";
import { camelize, isRecord } from "./records.ts";
import type { JsonRecord } from "./types.ts";

export function rpcRecord(value: unknown, resource = "resource"): JsonRecord {
    const payload = camelize(value);
    if (!isRecord(payload)) {
        throw new HttpError(502, `invalid ${resource} response`);
    }
    const code = typeof payload.code === "string" ? payload.code : undefined;
    if (payload.state === "not_found") {
        throw new HttpError(404, `${resource} not found`);
    }
    if (payload.state === "conflict") {
        throw new HttpError(409, code ?? `${resource} conflict`);
    }
    if (payload.state === "invalid") {
        throw new HttpError(422, code ?? `invalid ${resource}`);
    }
    if (typeof payload.state === "string" && payload.state !== "ok") {
        throw new HttpError(502, `invalid ${resource} state`);
    }
    return payload;
}

export function rpcEntity(value: unknown, key: string, resource = key): JsonRecord {
    const payload = rpcRecord(value, resource);
    const entity = payload[key];
    if (!isRecord(entity)) {
        throw new HttpError(502, `invalid ${resource} response`);
    }
    return entity;
}

export type JsonRecord = Record<string, unknown>;

export interface Page<T = unknown> {
    items: T[];
    nextCursor: string | null;
}

export interface PartnerAccount {
    id: number;
    cmsUserId: string;
    displayName: string;
}

import { requireCmsRequest } from "./core/auth.ts";
import { handleError, json, optionsResponse } from "./core/http.ts";
import { handleAdminRoute } from "./routing/admin.ts";
import { handlePartnerRoute } from "./routing/partner.ts";
import { handlePublicRoute } from "./routing/public.ts";

const routeHandlers = [handlePublicRoute, handlePartnerRoute, handleAdminRoute];

export async function handleSalesConfiguratorRequest(request: Request): Promise<Response> {
    try {
        if (request.method === "OPTIONS") {
            return optionsResponse();
        }
        requireCmsRequest(request);
        const route = routePath(request);
        for (const handler of routeHandlers) {
            const response = await handler(route, request);
            if (response) {
                return response;
            }
        }
        return json({ error: "not found" }, 404);
    } catch (error) {
        return handleError(error);
    }
}

function routePath(request: Request): string {
    const pathname = new URL(request.url).pathname.replace(/\/+$/, "");
    const marker = "/cms-sales-configurator";
    const index = pathname.indexOf(marker);
    if (index === -1) {
        return pathname || "/";
    }
    return pathname.slice(index + marker.length) || "/";
}

import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import { addSearch, listQuery } from "../../services/query.ts";
import { camelize, integer } from "../../core/records.ts";
import { listRows, one, restJson } from "../../core/rest.ts";
import type { JsonRecord } from "../../core/types.ts";

const itemSelect = "id,kind,code,name,description,status,sort_order,created_at,updated_at";

export async function listCatalogItems(request: Request): Promise<Response> {
    const query = listQuery(request);
    const params = new URLSearchParams({
        select: itemSelect,
        order: "kind.asc,sort_order.asc,id.asc",
        limit: String(query.limit),
        offset: String(query.offset),
    });
    if (query.status) {
        params.set("status", `eq.${query.status}`);
    }
    addSearch(params, query.query, "name", "code", "description");
    const { rows, total } = await listRows(`catalog_items?${params}`);
    return json({
        items: camelize(rows.map(catalogLookupItem)),
        total,
        limit: query.limit,
        offset: query.offset,
    });
}

export async function listCatalogKind(request: Request, kind: string): Promise<Response> {
    const query = listQuery(request);
    const params = new URLSearchParams({
        select: itemSelect,
        kind: `eq.${kind}`,
        order: "sort_order.asc,id.asc",
        limit: String(query.limit),
        offset: String(query.offset),
    });
    if (query.status) {
        params.set("status", `eq.${query.status}`);
    }
    if (kind === "variant") {
        const moduleId = integer(new URL(request.url).searchParams.get("moduleItemId"), "moduleItemId");
        if (moduleId) {
            const variants = await restJson<JsonRecord[]>(
                `catalog_variants?select=item_id&module_item_id=eq.${moduleId}`,
            );
            if (!variants.length) {
                return json({ items: [], total: 0, limit: query.limit, offset: query.offset });
            }
            params.set("id", `in.(${variants.map((row) => row.item_id).join(",")})`);
        }
    }
    addSearch(params, query.query, "name", "code", "description");
    const { rows, total } = await listRows(`catalog_items?${params}`);
    const items = kind === "variant" ? await hydrateVariants(rows) : rows;
    return json({ items: camelize(items), total, limit: query.limit, offset: query.offset });
}

export async function getCatalogKind(request: Request, kind: string): Promise<Response> {
    const idValue = new URL(request.url).searchParams.get("id");
    if (idValue === "__new__") {
        return json(newCatalogKind(kind));
    }
    const id = integer(idValue, "id", true)!;
    const item = await one("catalog_items", { id, kind }, itemSelect);
    if (!item) {
        throw new HttpError(404, `${kind} not found`);
    }
    const details = await one(subtypeTable(kind), { item_id: id });
    if (!details) {
        throw new HttpError(404, `${kind} not found`);
    }
    if (kind !== "variant") {
        return json(camelize({ ...item, ...details }));
    }
    const module = await one("catalog_items", { id: Number(details.module_item_id), kind: "module" }, "id,name");
    return json(camelize({ ...item, ...details, module_name: module?.name }));
}

function catalogLookupItem(item: JsonRecord): JsonRecord {
    return {
        ...item,
        lookup_subtitle: `${String(item.kind)} · ${String(item.code)}`,
    };
}

function newCatalogKind(kind: string): JsonRecord {
    const item = {
        id: null,
        code: "",
        name: "",
        description: null,
        status: "draft",
        sortOrder: 0,
    };
    if (kind === "module" || kind === "feature") {
        return item;
    }
    if (kind === "variant") {
        return {
            ...item,
            moduleItemId: null,
            moduleName: "",
            providerName: null,
            pricingMode: "fixed",
            unitAmountCents: null,
            currency: "EUR",
        };
    }
    throw new HttpError(500, "unsupported catalogue kind");
}

async function hydrateVariants(rows: JsonRecord[]): Promise<JsonRecord[]> {
    if (!rows.length) {
        return [];
    }
    const ids = rows.map((row) => Number(row.id));
    const details = await restJson<JsonRecord[]>(`catalog_variants?select=*&item_id=in.(${ids.join(",")})`);
    const byId = new Map(details.map((detail) => [Number(detail.item_id), detail]));
    const modules = await catalogItemsFor(details, "module_item_id");
    return rows.map((row) => {
        const detail = byId.get(Number(row.id)) ?? {};
        return {
            ...row,
            ...detail,
            module_name: modules.get(Number(detail.module_item_id))?.name,
        };
    });
}

async function catalogItemsFor(rows: JsonRecord[], ...fields: string[]): Promise<Map<number, JsonRecord>> {
    const ids = [
        ...new Set(rows.flatMap((row) => fields.map((field) => Number(row[field]))).filter(Number.isSafeInteger)),
    ];
    if (!ids.length) {
        return new Map();
    }
    const items = await restJson<JsonRecord[]>(`catalog_items?select=id,kind,code,name&id=in.(${ids.join(",")})`);
    return new Map(items.map((item) => [Number(item.id), item]));
}

function subtypeTable(kind: string): string {
    if (!["module", "variant", "feature"].includes(kind)) {
        throw new HttpError(500, "unsupported catalogue kind");
    }
    return `catalog_${kind}s`;
}

import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import { camelize, integer } from "../../core/records.ts";
import { listRows, restJson } from "../../core/rest.ts";
import type { JsonRecord } from "../../core/types.ts";
import { catalogRequirementProjection } from "../../services/catalog.ts";
import { listQuery } from "../../services/query.ts";

export async function listVariantFeatures(request: Request): Promise<Response> {
    const query = listQuery(request);
    const params = listParams(query, "sort_order.asc,variant_item_id.asc,feature_item_id.asc");
    const url = new URL(request.url);
    const selection = relationshipSelection(url.searchParams.get("id"), "variant feature");
    if (selection === "new") {
        return relationshipDraft(
            {
                id: "__new__",
                variantItemId: null,
                variantName: null,
                variant: null,
                featureItemId: null,
                featureName: null,
                feature: null,
                availability: "included",
                pricingMode: "included",
                unitAmountCents: null,
                sortOrder: 0,
            },
            query,
        );
    }
    const variantId = selection?.left ?? integer(url.searchParams.get("variantItemId"), "variantItemId");
    const featureId = selection?.right ?? integer(url.searchParams.get("featureItemId"), "featureItemId");
    addExactFilter(params, "variant_item_id", variantId);
    addExactFilter(params, "feature_item_id", featureId);
    if (!(await addSearchFilter(params, query.query, "variant_item_id", "feature_item_id"))) {
        return emptyList(query);
    }
    const { rows, total } = await listRows(`variant_features?${params}`);
    const items = await catalogItemsFor(rows, "variant_item_id", "feature_item_id");
    const hydrated = rows.map((row) => {
        const variantItemId = Number(row.variant_item_id);
        const featureItemId = Number(row.feature_item_id);
        const variant = items.get(variantItemId);
        const feature = items.get(featureItemId);
        return {
            ...row,
            id: relationshipId(variantItemId, featureItemId),
            variant_name: variant?.name,
            variant: catalogItemSelection(variant),
            feature_name: feature?.name,
            feature: catalogItemSelection(feature),
        };
    });
    return relationshipList(hydrated, total, query, Boolean(variantId && featureId));
}

export async function listRequirements(request: Request): Promise<Response> {
    const query = listQuery(request);
    const params = listParams(query, "created_at.desc,subject_item_id.asc");
    const url = new URL(request.url);
    const selection = relationshipSelection(url.searchParams.get("id"), "prerequisite");
    if (selection === "new") {
        return relationshipDraft(
            {
                id: "__new__",
                subjectItemId: null,
                subjectKind: null,
                subjectCode: null,
                subjectName: null,
                subject: null,
                requiredItemId: null,
                requiredKind: null,
                requiredCode: null,
                requiredName: null,
                required: null,
                createdAt: null,
            },
            query,
        );
    }
    const subjectId = selection?.left ?? integer(url.searchParams.get("subjectItemId"), "subjectItemId");
    const requiredId = selection?.right ?? integer(url.searchParams.get("requiredItemId"), "requiredItemId");
    addExactFilter(params, "subject_item_id", subjectId);
    addExactFilter(params, "required_item_id", requiredId);
    if (!(await addSearchFilter(params, query.query, "subject_item_id", "required_item_id"))) {
        return emptyList(query);
    }
    const { rows, total } = await listRows(`catalog_requirements?${params}`);
    const items = await catalogItemsFor(rows, "subject_item_id", "required_item_id");
    const hydrated = rows.map((row) => requirementProjection(row, items));
    return relationshipList(hydrated, total, query, Boolean(subjectId && requiredId));
}

export async function requirementByIds(subjectItemId: number, requiredItemId: number): Promise<JsonRecord> {
    const items = await catalogItemsFor(
        [{ subject_item_id: subjectItemId, required_item_id: requiredItemId }],
        "subject_item_id",
        "required_item_id",
    );
    if (!items.has(subjectItemId) || !items.has(requiredItemId)) {
        throw new HttpError(502, "catalog requirement items are incomplete");
    }
    return camelize(
        requirementProjection({ subject_item_id: subjectItemId, required_item_id: requiredItemId }, items),
    ) as JsonRecord;
}

export async function variantFeatureWithSelections(
    variantItemId: number,
    featureItemId: number,
    variantFeature: JsonRecord,
): Promise<JsonRecord> {
    const items = await catalogItemsFor(
        [{ variant_item_id: variantItemId, feature_item_id: featureItemId }],
        "variant_item_id",
        "feature_item_id",
    );
    const variant = items.get(variantItemId);
    const feature = items.get(featureItemId);
    if (!variant || !feature) {
        throw new HttpError(502, "variant feature items are incomplete");
    }
    return camelize({
        ...variantFeature,
        id: relationshipId(variantItemId, featureItemId),
        variantName: variant.name,
        variant: catalogItemSelection(variant),
        featureName: feature.name,
        feature: catalogItemSelection(feature),
    }) as JsonRecord;
}

async function addSearchFilter(
    params: URLSearchParams,
    query: string | undefined,
    left: string,
    right: string,
): Promise<boolean> {
    const ids = await matchingCatalogItemIds(query);
    if (!ids) {
        return true;
    }
    if (!ids.length) {
        return false;
    }
    const filter = `in.(${ids.join(",")})`;
    params.set("or", `(${left}.${filter},${right}.${filter})`);
    return true;
}

async function matchingCatalogItemIds(query: string | undefined): Promise<number[] | undefined> {
    if (!query) {
        return undefined;
    }
    const params = new URLSearchParams({
        select: "id",
        or: `(name.ilike.*${query}*,code.ilike.*${query}*)`,
        limit: "1000",
    });
    const rows = await restJson<JsonRecord[]>(`catalog_items?${params}`);
    return rows.map((row) => Number(row.id)).filter(Number.isSafeInteger);
}

async function catalogItemsFor(rows: JsonRecord[], ...fields: string[]): Promise<Map<number, JsonRecord>> {
    const ids = [
        ...new Set(rows.flatMap((row) => fields.map((field) => Number(row[field]))).filter(Number.isSafeInteger)),
    ];
    if (!ids.length) {
        return new Map();
    }
    const items = await restJson<JsonRecord[]>(`catalog_items?select=id,kind,code,name&id=in.(${ids.join(",")})`);
    return new Map(items.map((item) => [Number(item.id), item]));
}

function listParams(query: ReturnType<typeof listQuery>, order: string): URLSearchParams {
    return new URLSearchParams({
        select: "*",
        order,
        limit: String(query.limit),
        offset: String(query.offset),
    });
}

function addExactFilter(params: URLSearchParams, field: string, value: number | undefined): void {
    if (value) {
        params.set(field, `eq.${value}`);
    }
}

function relationshipList(
    rows: JsonRecord[],
    total: number,
    query: ReturnType<typeof listQuery>,
    includeItem: boolean,
): Response {
    return json({
        items: camelize(rows),
        ...(includeItem && rows[0] ? { item: camelize(rows[0]) } : {}),
        total,
        limit: query.limit,
        offset: query.offset,
    });
}

function emptyList(query: ReturnType<typeof listQuery>): Response {
    return json({ items: [], total: 0, limit: query.limit, offset: query.offset });
}

function relationshipDraft(item: JsonRecord, query: ReturnType<typeof listQuery>): Response {
    return json({ items: [], item, total: 0, limit: query.limit, offset: query.offset });
}

function requirementProjection(requirement: JsonRecord, items: Map<number, JsonRecord>): JsonRecord {
    const subjectItemId = Number(requirement.subject_item_id);
    const requiredItemId = Number(requirement.required_item_id);
    return {
        ...catalogRequirementProjection(requirement, items),
        id: relationshipId(subjectItemId, requiredItemId),
        subject: catalogItemSelection(items.get(subjectItemId)),
        required: catalogItemSelection(items.get(requiredItemId)),
    };
}

function catalogItemSelection(item: JsonRecord | undefined): JsonRecord | null {
    if (!item) {
        return null;
    }
    return {
        id: item.id,
        kind: item.kind,
        code: item.code,
        name: item.name,
        lookup_subtitle: `${String(item.kind)} · ${String(item.code)}`,
    };
}

function relationshipId(left: number, right: number): string {
    return `${left}:${right}`;
}

function relationshipSelection(
    value: string | null,
    label: string,
): { left: number; right: number } | "new" | undefined {
    if (!value) {
        return undefined;
    }
    if (value === "__new__") {
        return "new";
    }
    const match = /^([1-9]\d*):([1-9]\d*)$/.exec(value);
    if (!match) {
        throw new HttpError(400, `${label} id must contain two positive integers`);
    }
    const left = Number(match[1]);
    const right = Number(match[2]);
    if (!Number.isSafeInteger(left) || !Number.isSafeInteger(right)) {
        throw new HttpError(400, `${label} id must contain two positive integers`);
    }
    return { left, right };
}

import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import {
    enumValue,
    integer,
    nonNegativeInteger,
    queryInteger,
    readJsonObject,
    requiredText,
    text,
} from "../../core/records.ts";
import { rpc } from "../../core/rest.ts";
import { rpcEntity, rpcRecord } from "../../core/rpc-result.ts";
import { requirementByIds, variantFeatureWithSelections } from "./catalog-relationships.ts";

const itemStatuses = ["draft", "published", "archived"] as const;

export async function upsertCatalogItem(request: Request, kind: string): Promise<Response> {
    const body = await readJsonObject(request);
    const payload: Record<string, unknown> = {
        code: requiredText(body.code, "code"),
        name: requiredText(body.name, "name"),
        description: text(body.description) ?? null,
        status: enumValue(body.status, "status", itemStatuses) ?? "draft",
        sort_order: nonNegativeInteger(body.sortOrder, "sortOrder") ?? 0,
    };
    if (kind === "variant") {
        payload.module_item_id = integer(body.moduleItemId, "moduleItemId", true);
        payload.provider_name = text(body.providerName) ?? null;
        payload.pricing_mode = enumValue(body.pricingMode, "pricingMode", ["fixed", "quote"], true);
        payload.unit_amount_cents = money(body.unitAmountCents, "unitAmountCents");
        payload.currency = text(body.currency) ?? "EUR";
    }
    const result = await rpc(`upsert_catalog_${kind}`, {
        p_item_id: queryInteger(request, "id") ?? integer(body.id, "id") ?? null,
        p_payload: payload,
    });
    return json(rpcEntity(result, kind, `catalog ${kind}`));
}

export async function upsertVariantFeature(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const result = await rpc("upsert_variant_feature", {
        p_variant_item_id: integer(body.variantItemId, "variantItemId", true),
        p_feature_item_id: integer(body.featureItemId, "featureItemId", true),
        p_payload: {
            availability: enumValue(body.availability, "availability", ["included", "optional"], true),
            pricing_mode: enumValue(body.pricingMode, "pricingMode", ["included", "fixed", "quote"], true),
            unit_amount_cents: money(body.unitAmountCents, "unitAmountCents"),
            sort_order: nonNegativeInteger(body.sortOrder, "sortOrder") ?? 0,
        },
    });
    const entity = rpcEntity(result, "variantFeature", "variant feature");
    const variantItemId = integer(entity.variantItemId, "variantItemId", true)!;
    const featureItemId = integer(entity.featureItemId, "featureItemId", true)!;
    return json(await variantFeatureWithSelections(variantItemId, featureItemId, entity));
}

export async function deleteVariantFeature(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    const variantItemId = integer(params.get("variantItemId"), "variantItemId", true)!;
    const featureItemId = integer(params.get("featureItemId"), "featureItemId", true)!;
    const result = rpcRecord(
        await rpc("delete_variant_feature", {
            p_variant_item_id: variantItemId,
            p_feature_item_id: featureItemId,
        }),
        "variant feature",
    );
    return json({
        deleted: result.deleted === true,
        variantItemId,
        featureItemId,
    });
}

export async function upsertRequirement(request: Request): Promise<Response> {
    const body = await readJsonObject(request);
    const result = await rpc("upsert_catalog_requirement", {
        p_subject_item_id: integer(body.subjectItemId, "subjectItemId", true),
        p_required_item_id: integer(body.requiredItemId, "requiredItemId", true),
    });
    rpcRecord(result, "catalog requirement");
    return json(
        await requirementByIds(
            integer(body.subjectItemId, "subjectItemId", true)!,
            integer(body.requiredItemId, "requiredItemId", true)!,
        ),
    );
}

export async function deleteRequirement(request: Request): Promise<Response> {
    const params = new URL(request.url).searchParams;
    const subjectItemId = integer(params.get("subjectItemId"), "subjectItemId", true)!;
    const requiredItemId = integer(params.get("requiredItemId"), "requiredItemId", true)!;
    const result = rpcRecord(
        await rpc("delete_catalog_requirement", {
            p_subject_item_id: subjectItemId,
            p_required_item_id: requiredItemId,
        }),
        "catalog requirement",
    );
    return json({
        deleted: result.deleted === true,
        subjectItemId,
        requiredItemId,
    });
}

function money(value: unknown, name: string): number | null {
    if (value === undefined || value === null || value === "") {
        return null;
    }
    const result = typeof value === "number" ? value : Number(value);
    if (!Number.isSafeInteger(result) || result < 0) {
        throw new HttpError(400, `${name} must be a non-negative integer`);
    }
    return result;
}

import { HttpError } from "../../core/errors.ts";
import { json } from "../../core/http.ts";
import { addSearch, listQuery } from "../../services/query.ts";
import {
    camelize,
    enumValue,
    integer,
    opaqueText,
    queryInteger,
    readJsonObject,
    requiredText,
    text,
} from "../../core/records.ts";
import { listRows, one, restJson, rpc } from "../../core/rest.ts";
import { rpcEntity, rpcRecord } from "../../core/rpc-result.ts";
import type { JsonRecord } from "../../core/types.ts";

const capabilities = ["clients.manage", "proposals.manage", "proposals.publish", "proposals.share"] as const;
const partnerSelect = "id,cms_user_id,status,display_name,contact_email,created_at,updated_at";

export async function listPartners(request: Request): Promise<Response> {
    const query = listQuery(request);
    const params = new URLSearchParams({
        select: partnerSelect,
        order: "updated_at.desc,id.desc",
        limit: String(query.limit),
        offset: String(query.offset),
    });
    if (query.status) {
        params.set("status", `eq.${query.status}`);
    }
    addSearch(params, query.query, "display_name", "contact_email", "cms_user_id");
    const { rows, total } = await listRows(`partner_accounts?${params}`);
    const capabilities = await capabilitiesFor(rows.map((row) => Number(row.id)));
    const items = rows.map((row) => ({
        ...row,
        capabilities: capabilities.get(Number(row.id)) ?? [],
