import type { JsonRecord } from "../core/types.ts";

interface CatalogRows {
    items: JsonRecord[];
    modules: JsonRecord[];
    variants: JsonRecord[];
    features: JsonRecord[];
    variantFeatures: JsonRecord[];
    requirements: JsonRecord[];
}

export function partnerCatalogProjection(rows: CatalogRows): JsonRecord {
    const items = new Map(rows.items.map((item) => [Number(item.id), item]));
    const moduleIds = new Set(rows.modules.map((module) => Number(module.item_id)));
    const featureIds = new Set(rows.features.map((feature) => Number(feature.item_id)));
    const variants = rows.variants
        .filter((variant) => items.get(Number(variant.item_id))?.status === "published")
        .sort(
            (left, right) =>
                Number(items.get(Number(left.item_id))?.sort_order ?? 0) -
                Number(items.get(Number(right.item_id))?.sort_order ?? 0),
        );
    const modules = rows.items
        .filter((item) => item.kind === "module" && item.status === "published" && moduleIds.has(Number(item.id)))
        .map((module) => ({
            ...itemSummary(module),
            requirements: requirementsFor(module.id, rows, items),
            variants: variants
                .filter((variant) => Number(variant.module_item_id) === Number(module.id))
                .map((variant) => variantProjection(variant, rows, items, featureIds)),
        }));

    return {
        modules,
        selection_rows: selectionRowsFor(modules),
    };
}

function selectionRowsFor(modules: JsonRecord[]): JsonRecord[] {
    return modules.flatMap((module) => [
        selectionRow({
            item: module,
            kind: "module",
            typeLabel: "Module",
            depth: 0,
            moduleId: module.id,
            variantId: null,
            providerName: null,
            availability: "base",
            availabilityLabel: "Base",
            pricingMode: null,
            unitAmountCents: null,
            currency: null,
        }),
        ...recordList(module.variants).flatMap((variant) => [
            selectionRow({
                item: variant,
                kind: "variant",
                typeLabel: "Variant",
                depth: 1,
                moduleId: module.id,
                variantId: variant.id,
                providerName: variant.provider_name ?? null,
                availability: "selectable",
                availabilityLabel: "Selectable",
                pricingMode: variant.pricing_mode ?? null,
                unitAmountCents: variant.unit_amount_cents ?? null,
                currency: variant.currency ?? null,
            }),
            ...recordList(variant.features).map((feature) => {
                const availability = feature.availability === "included" ? "included" : "optional";
                return selectionRow({
                    item: feature,
                    kind: "feature",
                    typeLabel: "Feature",
                    depth: 2,
                    moduleId: module.id,
                    variantId: variant.id,
                    providerName: variant.provider_name ?? null,
                    availability,
                    availabilityLabel: availability === "included" ? "Included" : "Optional",
                    pricingMode: feature.pricing_mode ?? null,
                    unitAmountCents: feature.unit_amount_cents ?? null,
                    currency: feature.currency ?? variant.currency ?? null,
                });
            }),
        ]),
    ]);
}

function selectionRow(input: {
    item: JsonRecord;
    kind: "module" | "variant" | "feature";
    typeLabel: string;
    depth: number;
    moduleId: unknown;
    variantId: unknown;
    providerName: unknown;
    availability: string;
    availabilityLabel: string;
    pricingMode: unknown;
    unitAmountCents: unknown;
    currency: unknown;
}): JsonRecord {
    return {
        kind: input.kind,
        type_label: input.typeLabel,
        depth: input.depth,
        id: input.item.id,
        code: input.item.code,
        name: input.item.name,
        description: input.item.description ?? null,
        module_id: input.moduleId,
        variant_id: input.variantId,
        provider_name: input.providerName,
        availability: input.availability,
        availability_label: input.availabilityLabel,
        pricing_mode: input.pricingMode,
        unit_amount_cents: input.unitAmountCents,
        currency: input.currency,
        requirements: recordList(input.item.requirements),
    };
}

function recordList(value: unknown): JsonRecord[] {
    return Array.isArray(value) ? (value as JsonRecord[]) : [];
}

function variantProjection(
    variant: JsonRecord,
    rows: CatalogRows,
    items: Map<number, JsonRecord>,
    featureIds: Set<number>,
): JsonRecord {
    const item = items.get(Number(variant.item_id)) ?? {};
    const relationships = rows.variantFeatures.filter(
        (relationship) => Number(relationship.variant_item_id) === Number(variant.item_id),
    );
    return {
        ...itemSummary(item),
        provider_name: variant.provider_name,
        pricing_mode: variant.pricing_mode,
        unit_amount_cents: variant.unit_amount_cents,
        currency: variant.currency,
        features: relationships.flatMap((relationship) => {
            const featureId = Number(relationship.feature_item_id);
            const feature = items.get(featureId);
            if (!feature || feature.status !== "published" || !featureIds.has(featureId)) {
                return [];
            }
            return [
                {
                    ...itemSummary(feature),
                    availability: relationship.availability,
                    pricing_mode: relationship.pricing_mode,
                    unit_amount_cents: relationship.unit_amount_cents,
                    currency: variant.currency,
                    requirements: requirementsFor(featureId, rows, items),
                },
            ];
        }),
        requirements: requirementsFor(variant.item_id, rows, items),
    };
}

function requirementsFor(subjectId: unknown, rows: CatalogRows, items: Map<number, JsonRecord>): JsonRecord[] {
    return rows.requirements
        .filter((requirement) => Number(requirement.subject_item_id) === Number(subjectId))
        .map((requirement) => catalogRequirementProjection(requirement, items));
}

export function catalogRequirementProjection(requirement: JsonRecord, items: Map<number, JsonRecord>): JsonRecord {
    const subject = items.get(Number(requirement.subject_item_id)) ?? {};
    const required = items.get(Number(requirement.required_item_id)) ?? {};
    return {
        subject_item_id: requirement.subject_item_id,
        subject_kind: subject.kind,
        subject_code: subject.code,
        subject_name: subject.name,
        required_item_id: requirement.required_item_id,
        required_kind: required.kind,
        required_code: required.code,
        required_name: required.name,
        created_at: requirement.created_at,
    };
}

function itemSummary(item: JsonRecord): JsonRecord {
    return {
        id: item.id,
        code: item.code,
        name: item.name,
        description: item.description,
    };
}

import { cmsUserId } from "../core/auth.ts";
import { HttpError } from "../core/errors.ts";
import { one } from "../core/rest.ts";
import type { PartnerAccount } from "../core/types.ts";

export type PartnerCapability = "clients.manage" | "proposals.manage" | "proposals.publish" | "proposals.share";

export async function requirePartner(request: Request, capability?: PartnerCapability): Promise<PartnerAccount> {
    const actor = cmsUserId(request);
    const account = await one(
        "partner_accounts",
        { cms_user_id: actor, status: "active" },
        "id,cms_user_id,display_name",
    );
    if (!account) {
        throw new HttpError(403, "active sales partner account required");
    }
    if (capability) {
        const grant = await one("partner_capabilities", {
            partner_account_id: Number(account.id),
            capability,
        });
        if (!grant) {
            throw new HttpError(403, `partner capability required: ${capability}`);
        }
    }
    return {
        id: Number(account.id),
        cmsUserId: String(account.cms_user_id),
        displayName: String(account.display_name),
    };
}

import { isRecord } from "../core/records.ts";
import type { JsonRecord } from "../core/types.ts";

export function stripOkState(value: unknown): unknown {
    if (!isRecord(value) || value.state !== "ok") {
        return value;
    }
    const { state: _, ...result } = value;
    return result;
}

export function partnerProposalProjection(value: unknown): JsonRecord | null {
    if (!isRecord(value) || value.state !== "ok") {
        return null;
    }
    const stripped = stripOkState(value);
    if (!isRecord(stripped) || !isRecord(stripped.proposal)) {
        return null;
    }
    const proposal = stripped.proposal;
    const draft = isRecord(proposal.draftVersion) ? proposal.draftVersion : null;
    return {
        ...stripped,
        proposal: {
            ...proposal,
            events: redactPartnerEventActors(proposal.events),
            missingRequirements: proposal.missingRequirements ?? draft?.missingRequirements ?? [],
        },
    };
}

function redactPartnerEventActors(value: unknown): unknown {
    if (!Array.isArray(value)) {
        return value;
    }
    return value.map((entry) => {
        if (!isRecord(entry)) {
            return entry;
        }
        const { actorId: _, actor_id: __, ...event } = entry;
        return event;
    });
}

export function publicProposalProjection(value: unknown): JsonRecord | null {
    if (!isRecord(value) || value.state !== "ok" || !isRecord(value.proposal)) {
        return null;
    }
    const proposal = value.proposal;
    const version = isRecord(proposal.version) ? proposal.version : proposal;
    const salesContact = publicSalesContact(version.salesContact);
    const items = publicItems(version.items);
    if (
        typeof proposal.reference !== "string" ||
        typeof proposal.status !== "string" ||
        typeof version.publishedAt !== "string" ||
        typeof version.currency !== "string" ||
        typeof version.fixedTotalCents !== "number" ||
        typeof version.quoteItemCount !== "number" ||
        !salesContact ||
        !items
    ) {
        return null;
    }
    return {
        proposal: {
            reference: proposal.reference,
            status: proposal.status,
            title: proposal.title,
            introduction: proposal.introduction,
            publishedAt: version.publishedAt,
            currency: version.currency,
            fixedTotalCents: version.fixedTotalCents,
            quoteItemCount: version.quoteItemCount,
            salesContact,
            items,
        },
    };
}

function publicSalesContact(value: unknown): JsonRecord | null {
    if (!isRecord(value) || typeof value.displayName !== "string") {
        return null;
    }
    return {
        displayName: value.displayName,
        email: value.email ?? value.contactEmail,
    };
}

function publicItems(value: unknown, parentSortOrder: unknown = null): JsonRecord[] | null {
    if (!Array.isArray(value)) {
        return null;
    }
    const result: JsonRecord[] = [];
    for (const item of value) {
        const projected = publicItem(item, parentSortOrder);
        if (!projected) {
            return null;
        }
        result.push(projected);
        if (isRecord(item) && item.children !== undefined) {
            const children = publicItems(item.children, item.sortOrder);
            if (!children) {
                return null;
            }
            result.push(...children);
        }
    }
    return result;
}

function publicItem(value: unknown, parentSortOrder: unknown): JsonRecord | null {
    if (
        !isRecord(value) ||
        typeof value.kind !== "string" ||
        typeof value.origin !== "string" ||
        typeof value.label !== "string" ||
        typeof value.quantity !== "number" ||
        typeof value.pricingMode !== "string" ||
        typeof value.currency !== "string" ||
        typeof value.sortOrder !== "number"
    ) {
        return null;
    }
    return {
        parentSortOrder: value.parentSortOrder ?? parentSortOrder,
        depth:
            typeof value.depth === "number" ? value.depth : (value.parentSortOrder ?? parentSortOrder) === null ? 0 : 1,
        kind: value.kind,
        origin: value.origin,
        code: value.code,
        label: value.label,
        description: value.description,
        quantity: value.quantity,
        pricingMode: value.pricingMode,
        unitAmountCents: value.unitAmountCents,
        currency: value.currency,
        sortOrder: value.sortOrder,
    };
}

import { restJson } from "../core/rest.ts";
import type { JsonRecord } from "../core/types.ts";

export async function hydrateProposalSummaries(
    proposals: JsonRecord[],
    includePartners = false,
): Promise<JsonRecord[]> {
    if (!proposals.length) {
        return [];
    }
    const proposalIds = numericValues(proposals, "id");
    const clientIds = numericValues(proposals, "client_id");
    const [clients, versions, partners] = await Promise.all([
        rowsByNumericIds("clients", "id", clientIds, "id,company_name,contact_name"),
        rowsByNumericIds(
            "proposal_versions",
            "proposal_id",
            proposalIds,
            "proposal_id,version_number,state,currency,fixed_total_cents,quote_item_count",
        ),
        includePartners ? partnerRows(proposals) : Promise.resolve([]),
    ]);
    const clientsById = new Map(clients.map((client) => [Number(client.id), client]));
    const partnersById = new Map(partners.map((partner) => [Number(partner.id), partner]));
    const versionsByProposal = groupByNumber(versions, "proposal_id");

    return proposals.map((proposal) => {
        const version = currentVersion(versionsByProposal.get(Number(proposal.id)) ?? []);
        const client = clientsById.get(Number(proposal.client_id));
        return {
            id: proposal.id,
            reference: proposal.reference,
            status: proposal.status,
            title: proposal.title,
            client,
            ...(includePartners
                ? {
                      partner_display_name: partnersById.get(Number(proposal.partner_account_id))?.display_name ?? null,
                  }
                : {}),
            fixed_total_cents: version?.fixed_total_cents ?? 0,
            quote_item_count: version?.quote_item_count ?? 0,
            currency: version?.currency ?? "EUR",
            created_at: proposal.created_at,
            updated_at: proposal.updated_at,
        };
    });
}

export function currentVersion(versions: JsonRecord[]): JsonRecord | undefined {
    return (
        versions.find((version) => version.state === "draft") ??
        versions.find((version) => version.state === "published") ??
        versions[0]
    );
}

async function rowsByNumericIds(table: string, field: string, ids: number[], select: string): Promise<JsonRecord[]> {
    if (!ids.length) {
        return [];
    }
    return await restJson<JsonRecord[]>(`${table}?select=${select}&${field}=in.(${ids.join(",")})`);
}

async function partnerRows(proposals: JsonRecord[]): Promise<JsonRecord[]> {
    const ids = numericValues(proposals, "partner_account_id");
    if (!ids.length) {
        return [];
    }
    return await restJson<JsonRecord[]>(`partner_accounts?select=id,display_name&id=in.(${ids.join(",")})`);
}

function numericValues(rows: JsonRecord[], field: string): number[] {
    return [...new Set(rows.map((row) => Number(row[field])).filter(Number.isSafeInteger))];
}

function groupByNumber(rows: JsonRecord[], field: string): Map<number, JsonRecord[]> {
    const result = new Map<number, JsonRecord[]>();
    for (const row of rows) {
        const key = Number(row[field]);
        const values = result.get(key) ?? [];
        values.push(row);
        result.set(key, values);
    }
    return result;
}

import { integer, nonNegativeInteger, text } from "../core/records.ts";

export interface ListQuery {
    limit: number;
    offset: number;
    query?: string;
    status?: string;
}

export function listQuery(request: Request): ListQuery {
    const params = new URL(request.url).searchParams;
    return {
        limit: Math.min(integer(params.get("limit"), "limit") ?? 50, 100),
        offset: nonNegativeInteger(params.get("offset"), "offset") ?? 0,
        query: safeSearch(params.get("q")),
        status: text(params.get("status")),
    };
}

export function addSearch(params: URLSearchParams, query: string | undefined, ...columns: string[]): void {
    if (query && columns.length) {
        params.set("or", `(${columns.map((column) => `${column}.ilike.*${query}*`).join(",")})`);
    }
}

function safeSearch(value: string | null): string | undefined {
    return text(value)
        ?.replace(/[,*()[\]{}]/g, " ")
        .slice(0, 120);
}

export function createShareToken(): string {
    const bytes = crypto.getRandomValues(new Uint8Array(32));
    return toBase64Url(bytes);
}

export async function shareTokenHash(token: string): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(token));
    return Array.from(new Uint8Array(digest))
        .map((byte) => byte.toString(16).padStart(2, "0"))
        .join("");
}

function toBase64Url(bytes: Uint8Array): string {
    let binary = "";
    for (const byte of bytes) {
        binary += String.fromCharCode(byte);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

