drop trigger if exists catalog_items_lock_publication_write
    on sales_configurator.catalog_items;
create trigger catalog_items_lock_publication_write
before insert or update of status on sales_configurator.catalog_items
for each row execute function sales_configurator.lock_catalog_publication_write();

create or replace function sales_configurator.validate_catalog_publication_state()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
    v_item sales_configurator.catalog_items%rowtype;
begin
    select item.*
    into v_item
    from sales_configurator.catalog_items item
    where item.id = new.id;
    if not found then
        return null;
    end if;

    if not (
        (
            v_item.kind = 'module'
            and exists (
                select 1
                from sales_configurator.catalog_modules module
                where module.item_id = v_item.id
            )
        )
        or (
            v_item.kind = 'variant'
            and exists (
                select 1
                from sales_configurator.catalog_variants variant
                where variant.item_id = v_item.id
            )
        )
        or (
            v_item.kind = 'feature'
            and exists (
                select 1
                from sales_configurator.catalog_features feature
                where feature.item_id = v_item.id
            )
        )
    ) then
        raise exception 'invariant: catalogue item requires its matching subtype';
    end if;

    if v_item.status = 'published' then
        if exists (
            select 1
            from sales_configurator.catalog_requirements requirement
            join sales_configurator.catalog_items required
              on required.id = requirement.required_item_id
            where requirement.subject_item_id = v_item.id
              and required.status <> 'published'
        ) then
            raise exception 'validation: a published item requires only published items';
        end if;
        if v_item.kind = 'variant' and not exists (
            select 1
            from sales_configurator.catalog_variants variant
            join sales_configurator.catalog_items module_item
              on module_item.id = variant.module_item_id
             and module_item.kind = 'module'
             and module_item.status = 'published'
            where variant.item_id = v_item.id
        ) then
            raise exception 'validation: a published variant requires a published module';
        end if;
        if v_item.kind = 'variant' and exists (
            select 1
            from sales_configurator.variant_features relation
            join sales_configurator.catalog_items feature_item
              on feature_item.id = relation.feature_item_id
            where relation.variant_item_id = v_item.id
              and relation.availability = 'included'
              and feature_item.status <> 'published'
        ) then
            raise exception
                'validation: a published variant includes only published features';
        end if;
    else
        if exists (
            select 1
            from sales_configurator.catalog_requirements requirement
            join sales_configurator.catalog_items subject
              on subject.id = requirement.subject_item_id
             and subject.status = 'published'
            where requirement.required_item_id = v_item.id
        ) then
            raise exception 'validation: an item required by a published item must stay published';
        end if;
        if v_item.kind = 'module' and exists (
            select 1
            from sales_configurator.catalog_variants variant
            join sales_configurator.catalog_items variant_item
              on variant_item.id = variant.item_id
             and variant_item.status = 'published'
            where variant.module_item_id = v_item.id
        ) then
            raise exception 'validation: a module with published variants must stay published';
        end if;
        if v_item.kind = 'feature' and exists (
            select 1
            from sales_configurator.variant_features relation
            join sales_configurator.catalog_items variant_item
              on variant_item.id = relation.variant_item_id
             and variant_item.status = 'published'
            where relation.feature_item_id = v_item.id
              and relation.availability = 'included'
        ) then
            raise exception
                'validation: a feature included by a published variant must stay published';
        end if;
    end if;
    return null;
end;
$$;

drop trigger if exists catalog_items_validate_publication
    on sales_configurator.catalog_items;
create constraint trigger catalog_items_validate_publication
after insert or update of status on sales_configurator.catalog_items
deferrable initially deferred
for each row execute function sales_configurator.validate_catalog_publication_state();

create or replace function sales_configurator.reject_catalog_requirement_cycle()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
    v_old_subject_item_id bigint;
    v_old_required_item_id bigint;
    v_subject_status text;
    v_required_status text;
begin
    perform pg_catalog.pg_advisory_xact_lock(83472911);
    lock table sales_configurator.catalog_requirements
        in share row exclusive mode;

    if tg_op = 'UPDATE' then
        v_old_subject_item_id := old.subject_item_id;
        v_old_required_item_id := old.required_item_id;
    end if;
    if new.subject_item_id = new.required_item_id then
        raise exception 'validation: a catalogue item cannot require itself';
    end if;

    select subject.status, required.status
    into v_subject_status, v_required_status
    from sales_configurator.catalog_items subject
    join sales_configurator.catalog_items required
      on required.id = new.required_item_id
    where subject.id = new.subject_item_id;

    if v_subject_status = 'published' and v_required_status <> 'published' then
        raise exception 'validation: a published item requires only published items';
    end if;

    if exists (
        with recursive reachable(item_id) as (
            select new.required_item_id
            union
            select requirement.required_item_id
            from sales_configurator.catalog_requirements requirement
            join reachable parent on parent.item_id = requirement.subject_item_id
            where not (
                tg_op = 'UPDATE'
                and requirement.subject_item_id = v_old_subject_item_id
                and requirement.required_item_id = v_old_required_item_id
            )
        )
        select 1
        from reachable
        where item_id = new.subject_item_id
    ) then
        raise exception 'validation: catalogue requirement would create a cycle';
    end if;
    return new;
end;
$$;

drop trigger if exists catalog_requirements_reject_cycle
    on sales_configurator.catalog_requirements;
create trigger catalog_requirements_reject_cycle
before insert or update on sales_configurator.catalog_requirements
for each row execute function sales_configurator.reject_catalog_requirement_cycle();

create or replace function sales_configurator.assert_catalog_subtype_kind()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
    v_expected_kind text;
    v_actual_kind text;
begin
    perform pg_catalog.pg_advisory_xact_lock(83472911);
    v_expected_kind := case tg_table_name
        when 'catalog_modules' then 'module'
        when 'catalog_variants' then 'variant'
        when 'catalog_features' then 'feature'
        else null
    end;
    if v_expected_kind is null then
        raise exception 'invariant: unsupported catalogue subtype';
    end if;

    select item.kind
    into v_actual_kind
    from sales_configurator.catalog_items item
    where item.id = new.item_id;

    if v_actual_kind is distinct from v_expected_kind then
        raise exception
            'invariant: catalog item % must have kind %',
            new.item_id,
            v_expected_kind;
    end if;
    return new;
end;
$$;

drop trigger if exists catalog_modules_assert_kind on sales_configurator.catalog_modules;
create trigger catalog_modules_assert_kind
before insert or update on sales_configurator.catalog_modules
for each row execute function sales_configurator.assert_catalog_subtype_kind();

