create or replace function sales_configurator.transition_admin_proposal(
    p_actor_cms_user_id text,
    p_proposal_id bigint,
    p_status text
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
    v_actor text := sales_configurator.require_opaque_identifier(
        p_actor_cms_user_id,
        'actorCmsUserId',
        512
    );
    v_target_status text := pg_catalog.lower(pg_catalog.btrim(p_status));
    v_proposal sales_configurator.proposals%rowtype;
    v_revoked_share record;
begin
    if v_target_status not in (
        'draft',
        'shared',
        'viewed',
        'accepted',
        'rejected',
        'expired',
        'archived'
    ) then
        raise exception 'validation: unknown proposal status';
    end if;

    select proposal.*
    into v_proposal
    from sales_configurator.proposals proposal
    where proposal.id = p_proposal_id
    for update;
    if not found then
        return pg_catalog.jsonb_build_object('state', 'not_found');
    end if;
    if v_proposal.status = v_target_status then
        return sales_configurator.admin_proposal_json(v_proposal.id);
    end if;

    if not (
        (v_proposal.status = 'draft' and v_target_status = 'archived')
        or (
            v_proposal.status in ('shared', 'viewed')
            and v_target_status in (
                'accepted',
                'rejected',
                'expired',
                'archived'
            )
        )
        or (
            v_proposal.status in ('accepted', 'rejected', 'expired')
            and v_target_status = 'archived'
        )
    ) then
        return pg_catalog.jsonb_build_object(
            'state', 'conflict',
            'code', 'invalid_status_transition',
            'fromStatus', v_proposal.status,
            'toStatus', v_target_status
        );
    end if;

    if v_target_status in (
        'accepted',
        'rejected',
        'expired',
        'archived'
    ) then
        for v_revoked_share in
            update sales_configurator.proposal_shares share
            set revoked_at = pg_catalog.clock_timestamp()
            from sales_configurator.proposal_versions version
            where version.id = share.proposal_version_id
              and version.proposal_id = v_proposal.id
              and share.revoked_at is null
            returning share.id, share.proposal_version_id
        loop
            insert into sales_configurator.proposal_events (
                proposal_id,
                proposal_version_id,
                share_id,
                event_type,
                actor_type,
                actor_id,
                metadata
            )
            values (
                v_proposal.id,
                v_revoked_share.proposal_version_id,
                v_revoked_share.id,
                'share_revoked',
                'admin',
                v_actor,
                pg_catalog.jsonb_build_object(
                    'reason', 'proposal_status_changed',
                    'status', v_target_status
                )
            );
        end loop;
    end if;

    update sales_configurator.proposals proposal
    set status = v_target_status
    where proposal.id = v_proposal.id;

    insert into sales_configurator.proposal_events (
        proposal_id,
        event_type,
        actor_type,
        actor_id,
        metadata
    )
    values (
        v_proposal.id,
        'status_changed',
        'admin',
        v_actor,
        pg_catalog.jsonb_build_object(
            'fromStatus', v_proposal.status,
            'toStatus', v_target_status
        )
    );

    return sales_configurator.admin_proposal_json(v_proposal.id);
end;
$$;

create or replace function sales_configurator.create_partner_proposal_share(
    p_partner_account_id bigint,
    p_proposal_id bigint,
    p_expires_at timestamptz,
    p_token_hash text
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
    v_token_hash text := pg_catalog.lower(pg_catalog.btrim(p_token_hash));
    v_proposal sales_configurator.proposals%rowtype;
    v_version_id bigint;
    v_share sales_configurator.proposal_shares%rowtype;
begin
    if p_partner_account_id is null then
        raise exception 'validation: partnerAccountId is required';
    end if;

    if v_token_hash !~ '^[0-9a-f]{64}$' then
        raise exception 'validation: tokenHash must be a SHA-256 hex digest';
    end if;
    if p_expires_at is not null
        and p_expires_at <= pg_catalog.clock_timestamp()
    then
        raise exception 'validation: expiresAt must be in the future';
    end if;

    select proposal.*
    into v_proposal
    from sales_configurator.proposals proposal
    where proposal.id = p_proposal_id
      and proposal.partner_account_id = p_partner_account_id
    for update;
    if not found then
        return pg_catalog.jsonb_build_object('state', 'not_found');
    end if;
    if v_proposal.status in ('accepted', 'rejected', 'expired', 'archived') then
        return pg_catalog.jsonb_build_object(
            'state', 'conflict',
            'code', 'proposal_is_terminal'
        );
    end if;

    select version.id
    into v_version_id
    from sales_configurator.proposal_versions version
    where version.proposal_id = v_proposal.id
      and version.state = 'published'
    for key share;
    if not found then
        return pg_catalog.jsonb_build_object(
            'state', 'conflict',
            'code', 'proposal_is_not_published'
        );
    end if;

    insert into sales_configurator.proposal_shares (
        proposal_version_id,
        token_hash,
        expires_at
    )
    values (
        v_version_id,
        v_token_hash,
        p_expires_at
    )
    on conflict (token_hash) do nothing
    returning * into v_share;
    if not found then
        return pg_catalog.jsonb_build_object(
            'state', 'conflict',
            'code', 'token_hash_exists'
        );
    end if;

    update sales_configurator.proposals proposal
    set status = 'shared'
    where proposal.id = v_proposal.id;

    insert into sales_configurator.proposal_events (
        proposal_id,
        proposal_version_id,
        share_id,
        event_type,
        actor_type,
        actor_id,
        metadata
    )
    values (
        v_proposal.id,
        v_version_id,
        v_share.id,
        'share_created',
        'partner',
        p_partner_account_id::text,
        pg_catalog.jsonb_build_object('expiresAt', v_share.expires_at)
    );

    return sales_configurator.partner_proposal_json(
        v_proposal.id,
        p_partner_account_id
    )
        || pg_catalog.jsonb_build_object(
            'share', pg_catalog.jsonb_build_object(
                'id', v_share.id,
                'proposalVersionId', v_share.proposal_version_id,
                'expiresAt', v_share.expires_at,
                'revokedAt', v_share.revoked_at,
                'firstViewedAt', v_share.first_viewed_at,
                'lastViewedAt', v_share.last_viewed_at,
                'viewCount', v_share.view_count,
                'createdAt', v_share.created_at
            )
        );
end;
$$;

create or replace function sales_configurator.save_partner_proposal_draft(
    p_partner_account_id bigint,
    p_proposal_id bigint,
    p_client_id bigint,
    p_proposal jsonb,
    p_selections jsonb,
    p_custom_items jsonb
)
returns jsonb
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
    v_payload jsonb := sales_configurator.require_json_object(p_proposal, 'proposal');
    v_validation jsonb;
    v_prepared jsonb;
    v_totals jsonb;
    v_proposal_id bigint;
    v_version_id bigint;
    v_revision bigint;
begin
    if p_partner_account_id is null then
        raise exception 'validation: partnerAccountId is required';
    end if;

    if not exists (
        select 1
        from sales_configurator.clients client
        where client.id = p_client_id
          and client.partner_account_id = p_partner_account_id
    ) then
        return pg_catalog.jsonb_build_object('state', 'not_found');
    end if;
    if p_proposal_id is not null and not exists (
        select 1
        from sales_configurator.proposals proposal
        where proposal.id = p_proposal_id
          and proposal.partner_account_id = p_partner_account_id
    ) then
        return pg_catalog.jsonb_build_object('state', 'not_found');
    end if;

    v_validation := sales_configurator.validate_draft_selection(
        p_selections,
        p_custom_items
    );
    if v_validation ->> 'state' <> 'ok' then
        return v_validation;
    end if;

    v_prepared := sales_configurator.prepare_partner_proposal_draft(
        p_partner_account_id,
        p_proposal_id,
        p_client_id,
        v_payload
    );
    if v_prepared ->> 'state' <> 'ok' then
        return v_prepared;
    end if;

    v_proposal_id := (v_prepared ->> 'proposalId')::bigint;
    v_version_id := (v_prepared ->> 'versionId')::bigint;
    v_totals := sales_configurator.rebuild_draft_snapshot(
        v_version_id,
        p_selections,
        p_custom_items
    );

    update sales_configurator.proposal_versions version
    set
        currency = 'EUR',
        fixed_total_cents = (v_totals ->> 'fixedTotalCents')::bigint,
        quote_item_count = (v_totals ->> 'quoteItemCount')::integer,
        revision = version.revision + 1
    where version.id = v_version_id
    returning version.revision into v_revision;

    insert into sales_configurator.proposal_events (
        proposal_id,
        proposal_version_id,
        event_type,
        actor_type,
        actor_id,
        metadata
    )
    values (
        v_proposal_id,
        v_version_id,
        'draft_saved',
        'partner',
        p_partner_account_id::text,
        pg_catalog.jsonb_build_object(
            'versionNumber', (v_prepared ->> 'versionNumber')::integer,
            'revision', v_revision,
            'fixedTotalCents', (v_totals ->> 'fixedTotalCents')::bigint,
            'quoteItemCount', (v_totals ->> 'quoteItemCount')::integer
        )
    );

    return sales_configurator.partner_proposal_json(
        v_proposal_id,
        p_partner_account_id
    );
end;
$$;

create or replace function sales_configurator.assert_draft_selection_shape(
    p_selections jsonb,
    p_custom_items jsonb
)
returns void
language plpgsql
immutable
set search_path = ''
as $$
declare
    v_selection jsonb;
    v_feature_id jsonb;
    v_custom_item jsonb;
    v_optional_count integer := 0;
begin
    if pg_catalog.jsonb_typeof(p_selections) is distinct from 'array' then
        raise exception 'validation: selections must be an array';
    end if;
    if pg_catalog.jsonb_typeof(p_custom_items) is distinct from 'array' then
        raise exception 'validation: customItems must be an array';
    end if;
    if pg_catalog.jsonb_array_length(p_selections) > 100 then
        raise exception 'validation: at most 100 variants may be selected';
    end if;
    if pg_catalog.jsonb_array_length(p_custom_items) > 100 then
        raise exception 'validation: at most 100 custom items may be submitted';
    end if;
    if pg_catalog.jsonb_array_length(p_selections) = 0
        and pg_catalog.jsonb_array_length(p_custom_items) = 0
    then
        raise exception 'validation: at least one selection or custom item is required';
    end if;

    for v_selection in
        select value from pg_catalog.jsonb_array_elements(p_selections)
    loop
        if pg_catalog.jsonb_typeof(v_selection) <> 'object'
            or pg_catalog.jsonb_typeof(v_selection -> 'variantItemId') <> 'number'
            or pg_catalog.jsonb_typeof(v_selection -> 'optionalFeatureItemIds') <> 'array'
        then
            raise exception
                'validation: each selection requires variantItemId and optionalFeatureItemIds';
        end if;

        perform (v_selection ->> 'variantItemId')::bigint;
        v_optional_count := v_optional_count
            + pg_catalog.jsonb_array_length(v_selection -> 'optionalFeatureItemIds');

        for v_feature_id in
            select value
            from pg_catalog.jsonb_array_elements(
                v_selection -> 'optionalFeatureItemIds'
            )
        loop
            if pg_catalog.jsonb_typeof(v_feature_id) <> 'number' then
                raise exception 'validation: optional feature ids must be numbers';
            end if;
            perform v_feature_id::text::bigint;
        end loop;
    end loop;

    if v_optional_count > 500 then
        raise exception 'validation: at most 500 optional features may be selected';
    end if;

    for v_custom_item in
        select value from pg_catalog.jsonb_array_elements(p_custom_items)
    loop
        if pg_catalog.jsonb_typeof(v_custom_item) <> 'object' then
            raise exception 'validation: each custom item must be an object';
        end if;
        perform sales_configurator.require_bounded_text(
            v_custom_item ->> 'label',
            'customItem.label',
            300
        );
        perform sales_configurator.optional_bounded_text(
            v_custom_item ->> 'description',
            'customItem.description',
            10000
        );
        if v_custom_item ? 'quantity' then
            if pg_catalog.jsonb_typeof(v_custom_item -> 'quantity') <> 'number'
                or (v_custom_item ->> 'quantity')::integer not between 1 and 100000
            then
                raise exception 'validation: custom item quantity must be between 1 and 100000';
            end if;
        end if;
    end loop;
end;
$$;

