definitions/artifacts/sources/primary/en.content:
[
  {
    "endpointId": "manageFeature",
    "method": "GET",
    "access": "admin",
    "targetUrl": "{{connectors.supabase.functionsBaseUrl}}/cms-sales-configurator/admin/feature",
    "meta": {
      "name": "Manage feature",
      "description": "Read one feature or return defaults for a new feature."
    },
    "params": [
      { "name": "id", "in": "query", "type": "string" }
    ],
    "headers": {
      "$include": "../../../../shared/admin-headers.json"
    },
    "output": [
      {
        "status": "200",
        "body": {
          "$include": "../../../../shapes/catalog/feature.json"
        }
      },
      {
        "status": "default",
        "body": {
          "$include": "../../../../shared/error.json"
        }
      }
    ]
  }
]

[
  {
    "endpointId": "manageFeatures",
    "method": "GET",
    "access": "admin",
    "targetUrl": "{{connectors.supabase.functionsBaseUrl}}/cms-sales-configurator/admin/features",
    "meta": {
      "name": "Manage features",
      "description": "Search reusable commercial features for the administration dashboard."
    },
    "params": [
      { "name": "q", "in": "query", "type": "string" },
      { "name": "status", "in": "query", "type": "string" },
      { "name": "limit", "in": "query", "type": "number" },
      { "name": "offset", "in": "query", "type": "number" }
    ],
    "headers": {
      "$include": "../../../../shared/admin-headers.json"
    },
    "output": [
      {
        "status": "200",
        "body": {
          "type": "object",
          "properties": {
            "items": {
              "type": "array",
              "items": {
                "$include": "../../../../shapes/catalog/feature.json"
              }
